from huggingface_hub.utils import filter_repo_objects

from app.publish import RUN_IGNORE_PATTERNS, SUMMARIES_REPO, publish_run, publish_summary


class RecordingApi:
    def __init__(self):
        self.calls = []

    def upload_file(self, **kwargs):
        self.calls.append(kwargs)
        return SimpleNamespace(commit_url="https://huggingface.co/datasets/acme-ml/run-summaries/commit/abc")

    def create_repo(self, repo_id, **kwargs):
        self.calls.append(("create_repo", repo_id, kwargs))

    def upload_folder(self, **kwargs):
        self.calls.append(("upload_folder", kwargs))


def test_publish_run_creates_private_dataset_and_uploads_folder_at_root(tmp_path):
    api = RecordingApi()

    publish_run(tmp_path, "acme-ml/run-0007", api=api)

    (_, repo_id, create_kwargs), (_, upload_kwargs) = api.calls
    assert repo_id == "acme-ml/run-0007"
    assert create_kwargs == {"repo_type": "dataset", "private": True, "exist_ok": True}
    assert upload_kwargs["repo_id"] == "acme-ml/run-0007" and upload_kwargs["repo_type"] == "dataset"
    assert upload_kwargs["folder_path"] == tmp_path
    assert upload_kwargs.get("path_in_repo") in (None, "")


def test_run_ignore_patterns_skip_tmp_files_and_wandb():
    paths = ["metrics.json", "ckpt/step-100/model.safetensors", "ckpt/step-100/model.tmp", "shard.tmp",
             "wandb/run-1/files/log.txt", "data/wandb.parquet"]

    kept = list(filter_repo_objects(paths, ignore_patterns=list(RUN_IGNORE_PATTERNS)))

    assert kept == ["metrics.json", "ckpt/step-100/model.safetensors", "data/wandb.parquet"]

